//! Render the public protection catalogue from the policy consumed by the planner.
use dw4vhp_core::crown::encounters::{importable_models, protected_encounters};
use dw4vhp_core::crown::{RANDOM_DONORS, RANDOM_RULES_VERSION};
fn main() {
    println!("# Randomizer encounter rules\n\n<!-- Generated by npm run docs:rules. Edit the crown policy or this exporter and regenerate. -->\n");
    println!("Current randomizer rules version: **{RANDOM_RULES_VERSION}**.\n");
    println!("## Current rules\n");
    println!("1. **Seeded per stage.** Enemy choices are made when the image is built; revisiting a stage does not reroll them.");
    println!("2. **Resident families plus imports.** Each stage uses eligible native families and up to **{RANDOM_DONORS} imported families**. Unused imports are omitted.");
    println!("3. **Prefer a different family.** Select another compatible family when available; otherwise retain the native enemy.");
    println!("4. **Match combat strength and rarity.** Choose the closest HP/attack variant of the original crown rarity. Keep the replacement family consistent across difficulties.");
    println!("5. **Preserve rewards and encounter counts.** Keep the original EXP after selected Crown Mod settings. The four-player spawn option controls counts independently.");
    println!("6. **Respect encounter compatibility.** Preserve model-specific authored entrances; constrain kill-count quests to compatible residents. Exclude the developer world, practice stage and final-boss stages.");
    println!("7. **Make supported scripts follow replacements.** Supported intros, including Sukamon and Tortamon, retarget their named waits and control/cleanup commands. Mangrove's two pre-boss waves also randomize with matching waits and cleanup, retaining their counts and progression callbacks. Intro replacements are reserved from randomized patrols; wave replacements may share patrol families. ShogunGekomon's boss variants, its scene NPCs and other unsupported boss/script encounters remain native.\n");
    println!("## Importable enemy models\n\nThe following native model families can be imported, in selection order:\n");
    for model in importable_models() {
        println!("- `{model}`");
    }
    println!("\nRegular MR04 (`e_mecha4`) is included; the separate boss model (`e_mecha4bs`) is not an import candidate.\n");
    println!("## Fixed generator protections\n\n| Stage | Pack | Generators | Reason |\n| --- | --- | --- | --- |");
    for rule in protected_encounters() {
        let generators = rule
            .generators
            .iter()
            .map(|s| format!("`{s}`"))
            .collect::<Vec<_>>()
            .join(", ");
        println!(
            "| {} (`{}`) | {} | {} | {} |",
            rule.name, rule.stage, rule.pack_entry, generators, rule.reason
        );
    }
    println!("\n## Additional protections\n\nThese fixed records are not the entire exclusion policy. Authored spawn sequences keep their original models. Stage scripts that address an enemy family by native model name protect that family on the floor, except for explicitly reviewed exceptions. Boss families and native scripted encounters remain protected. Kill-count quests restrict replacements to their compatible resident families.\n\nThe developer world, practice stage and final-boss stages are excluded from enemy randomization. Cosmetic crowns are independent of these enemy-replacement rules.\n\nChanging eligibility, ordering or exceptions can change seeded output and requires a randomizer rules-version decision plus corresponding real-disc validation.");
}
